package apidocs

func (d *document) requestsAndInbox() {
	for _, kind := range []struct{ tag, path, id, record, page, input, decision, unavailable string }{
		{"Leave", "leaves", "leaveID", "LeaveRequest", "LeavePage", "SubmitLeave", "LeaveDecision", "leave_unavailable"},
		{"Late Access", "late-access-requests", "lateAccessID", "LateAccessRequest", "LateAccessPage", "SubmitLateAccess", "LateAccessDecision", "late_access_unavailable"},
	} {
		base := "/api/v1/" + kind.path
		detail := base + "/{" + kind.id + "}"
		d.op(kind.tag, "POST", base, "Submit own "+kind.tag+" request", student, kind.record, 201).body(kind.input).fail(413, "").fail(409, "Conflicting active request, changed request_id payload or active_student_required.").note("Generate a request_id once and retain it on exact retry; first creation AND replay return201. Future travel time required. Owner comes from authentication; no student_id/decision fields. Submission and approval never change scanned presence. Body maximum16KiB. Error on unavailable service: " + kind.unavailable + ".")
		d.op(kind.tag, "GET", base, "List "+kind.tag+" request history", staffReaders+",student", kind.page, 200).paging(0).query("student_id", uuidQuery(), "Staff Student filter. Student may select only their own profile; another profile gives403.").query("status", enumeration("pending", "approved", "rejected", "cancelled"), "Omit to retain all statuses, including cancelled.").note("created_at DESC then source UUID DESC. Totals and items are snapshot-consistent per response. Staff retain authorized archived history; Student ownership is enforced.")
		d.op(kind.tag, "GET", detail, "Get "+kind.tag+" request details", staffReaders+",student", kind.record, 200).note("Another Student's or missing record is concealed as404. Includes recorded decision/cancellation audit. Does not mark notifications read.")
		d.op(kind.tag, "POST", detail+"/decision", "Approve or reject "+kind.tag+" request", staffReaders, kind.record, 200).body(kind.decision).fail(413, "").fail(409, "State/time conflict or ineligible Student for approval.").note("Only pending requests may transition. Exact decision replay by the original actor preserves timestamp. Rejection requires a nonblank note. Cancellation/approval races have one winner. For late access, permission applies to one movement within +/-30 minutes of expected_at and is consumed by a matching scan.")
		d.op(kind.tag, "POST", detail+"/cancel", "Cancel own pending "+kind.tag+" request", student, kind.record, 200).fail(409, "Already approved/rejected or active_student_required; approved/consumed requests cannot be cancelled.").note("Omit body completely, even {}. Owner-only pending withdrawal; cancelled records remain in history. Exact retry preserves FIRST cancelled_at/cancelled_by. Does not create a decision, notification or attendance change. Another Student's record returns404 regardless of state.")
	}
	d.op("Leave", "POST", "/api/v1/going-home", "Declare Going Home without Warden approval", student, "GoingHomeDeclaration", 201).body("GoingHomeInput").success(200, "GoingHomeDeclaration", "Exact declaration replay").fail(413, "").fail(409, "already_outside, presence_unknown, going_home_pending, active_student_required or going_home_conflict.").note("Known IN presence required for a new declaration. Body has request_id only. No return time or approval. This records intention; it does not set OUT or waive restricted-hour permissions. The next recorded OUT scan marks departed.")
	d.op("Leave", "GET", "/api/v1/me/leave-allowance", "Get own yearly leave allowance summary", student, "LeaveAllowance", 200).query("year", object{"type": "integer", "minimum": 1, "maximum": 9998, "example": 2026}, "Optional FOUR-digit year (0001..9998); defaults to current Asia/Colombo year.").fail(409, "active_student_required.").note("Informational18-day allowance, never blocks requests. Only currently approved leave counts. Each Colombo date touched by [starts_at,ends_at) counts once; union overlaps, split across calendar years, include future approved leave. Midnight-exclusive ends do not charge the next date. Pending/rejected/cancelled, late access and Going Home do not count. remaining_days=max(18-used_days,0); exceeded_days=max(used_days-18,0). No selectors or body.")
	d.op("Leave", "GET", "/api/v1/me/passes", "List combined own leave and late-access history", student, "PassPage", 200).paging(1000000).query("type", enumeration("leave", "late_access"), "Omit for both request types.").query("status", enumeration("pending", "approved", "rejected", "cancelled"), "Current status; consumed approvals remain approved.").fail(409, "active_student_required.").note("Order: created_at DESC, type ASC (C/ASCII), source_id DESC. Use (type,source_id) for list identity; source_id addresses existing detail/cancel endpoints. Type-specific fields are null when inapplicable. Total and items share one snapshot, including empty pages. Separate requests can shift offsets after writes. Includes cancelled and consumed approvals; excludes Going Home. Reads do not modify sources or attendance. No student_id/user_id selectors.")
	d.op("Complaints", "POST", "/api/v1/complaints", "Submit own complaint", student, "Complaint", 201).body("SubmitComplaint").fail(413, "").fail(409, "complaint_conflict or active_student_required.").note("JSON request_id/category/description only. Exact creation replay returns201 with existing record. Categories are maintenance or disciplinary. Title/severity/multipart are not accepted. Add at most THREE images through separate raw-byte upload calls.")
	d.op("Complaints", "GET", "/api/v1/complaints", "List authorized complaints", complaintReaders, "ComplaintPage", 200).paging(0).query("student_id", uuidQuery(), "Staff filter; Student restricted to self.").query("category", enumeration("maintenance", "disciplinary"), "Sub-Warden can access maintenance only.").query("status", enumeration("pending", "in_progress", "resolved"), "Current complaint status.").query("created_from", object{"type": "string", "format": "date-time"}, "Inclusive submission timestamp.").query("created_to", object{"type": "string", "format": "date-time"}, "Exclusive submission timestamp; must be after created_from when both supplied.")
	d.op("Complaints", "GET", "/api/v1/complaints/{complaintID}", "Get authorized complaint", complaintReaders, "Complaint", 200).note("Student ownership and Sub-Warden maintenance scope enforced. Another Student's resource is concealed as404.")
	d.op("Complaints", "GET", "/api/v1/complaints/{complaintID}/updates", "List complaint progress timeline", complaintReaders, "ComplaintUpdatePage", 200).paging(0).note("Versioned chronological updates. Download photo content separately; private R2 keys are not exposed.")
	d.op("Complaints", "POST", "/api/v1/complaints/{complaintID}/notes", "Add version-checked complaint note", complaintReaders, "ComplaintUpdate", 200).body("ComplaintNote").fail(413, "").fail(409, "complaint_conflict: stale expected_version or changed idempotency payload.").note("Nonblank text required, maximum2000 code points. Use latest complaint version. Students can only note owned complaints; Sub-Warden maintenance only. Exact retries preserve the original update; do not rewrite expected_version on an uncertain retry.")
	d.op("Complaints", "POST", "/api/v1/complaints/{complaintID}/status", "Record complaint progress or resolution", staffReaders+",sub_warden", "ComplaintUpdate", 200).body("ComplaintStatus").fail(413, "").fail(409, "complaint_conflict: stale version or invalid lifecycle transition.").note("Staff-only; Sub-Warden maintenance only. status=in_progress or resolved. Nonblank resolution text required for resolved. request_id and latest expected_version protect safe retries and concurrent changes.")
	d.op("Complaints", "PUT", "/api/v1/complaints/{complaintID}/images/{imageID}", "Attach own pending complaint photo", student, "ComplaintImageResult", 201).upload().success(200, "ComplaintImageResult", "Exact upload replay").fail(409, "complaint_conflict: complaint not pending, three-image limit, removed ID or payload conflict.").note("Choose a new imageID UUID per attachment; retain ID and identical bytes on retry. Owner-only pending changes; upload increments complaint version. Up to3 JPEG/PNG photos,5MiB each, with decoded dimensions validated. R2 unavailable returns503 complaint_images_unavailable. Not multipart.")
	d.op("Complaints", "GET", "/api/v1/complaints/{complaintID}/images", "List authorized complaint photo metadata", complaintReaders, "ComplaintImageList", 200)
	d.op("Complaints", "GET", "/api/v1/complaints/{complaintID}/images/{imageID}", "Download private complaint photo", complaintReaders, "", 200).binary(200, "image/jpeg", "image/png").note("Authenticated bytes only; ownership and maintenance scope apply. No public R2 URL.")
	d.op("Complaints", "DELETE", "/api/v1/complaints/{complaintID}/images/{imageID}", "Remove own pending complaint photo", student, "ComplaintImageRemoval", 200).fail(409, "complaint_conflict: new removals require pending complaint.").note("Empty body. Replays preserve removal audit; increments complaint version for a new removal.")
	publication := d.op("Announcements", "POST", "/api/v1/announcements", "Publish all-Student or faculty announcement", staffReaders, "AnnouncementPublication", 201).body("PublishAnnouncement").success(200, "AnnouncementPublication", "Exact publication replay").fail(413, "").fail(409, "announcement_conflict: request_id reused with changed payload or target.").note("Audience defaults to all_students. For audience=faculty, include faculty (1-120 characters); it must match an existing unarchived Student faculty, case-insensitively. Faculty is trimmed/lowercased. No custom recipients or priority input. Publication snapshots active Student recipients in the target and queues durable inbox delivery. Exact retry does not republish or resnapshot. Omit faculty for all_students.")
	publication.data["requestBody"].(object)["content"].(object)["application/json"].(object)["examples"] = object{
		"all_students": object{"summary": "All Students", "value": object{"request_id": "10000000-0000-4000-8000-000000000001", "title": "Hostel meeting", "content": "All residents: please attend the hostel meeting.", "audience": "all_students"}},
		"faculty":      object{"summary": "One faculty (replace Science with an existing faculty)", "value": object{"request_id": "10000000-0000-4000-8000-000000000002", "title": "Faculty meeting", "content": "Science faculty residents: please attend the meeting.", "audience": "faculty", "faculty": "Science"}},
	}
	d.op("Announcements", "GET", "/api/v1/announcements", "List eligible announcement feed", staffReaders+",student", "AnnouncementPage", 200).paging(0).note("published_at DESC then announcement_id DESC. Admin/Warden see all; active Students with unarchived profiles see all_students plus their CURRENT faculty. Total and pagination use the same scope. Historical feed visibility does not fabricate delivery/read receipts.")
	d.op("Announcements", "GET", "/api/v1/announcements/{announcementID}", "Get eligible announcement content", staffReaders+",student", "Announcement", 200).note("Other-faculty Students receive404. Current faculty and profile eligibility also apply to inbox list/count/mark-read. Reading detail does not mark an inbox item read. Faculty changes never generate retroactive alerts; original delivery/read totals remain historical.")
	d.op("Announcements", "GET", "/api/v1/announcements/{announcementID}/delivery-summary", "Get publication delivery and read totals", staffReaders, "AnnouncementDeliverySummary", 200).note("recipients_total=delivered+pending_delivery; delivered=read+unread. Read state remains separate for each recipient.")
	d.op("Notifications", "GET", "/api/v1/notifications", "List owned eligible inbox", inboxReaders, "NotificationPage", 200).paging(1000000).query("unread", object{"type": "boolean"}, "True for unread only; omit or false for all eligible items.").note("Recipient is derived from authentication; source access is rechecked. Includes title, source_type, kind, optional category and source IDs, not message preview text. read_at=null means unread. Map display pills from source_type/kind/category. No /inbox alias, detail GET or read-all route.")
	d.op("Notifications", "GET", "/api/v1/notifications/unread-count", "Count owned unread inbox items", inboxReaders, "UnreadCount", 200).note("Eligible inbox count, not push delivery count.")
	d.op("Notifications", "POST", "/api/v1/notifications/{notificationID}/read", "Mark own notification read", inboxReaders, "Notification", 200).note("Empty body. Exact retry preserves FIRST read_at; another recipient's or inaccessible item returns404. Never changes another account's read state.")
	d.op("Notifications", "PUT", "/api/v1/me/push-devices/{deviceID}", "Register or refresh own FCM device token", allAccounts, "PushDevice", 200).body("RegisterPushDevice").fail(409, "push_device_conflict: token ownership/device limit conflict.").note("deviceID is a stable nonzero installation UUID, not a scanner UUID. Maximum10 active devices per user. Token is write-only; platform android/ios. No password or provider credentials. Backend FCM delivery enablement and real phone setup remain separate.")
	d.op("Notifications", "GET", "/api/v1/me/push-devices", "List own push device metadata", allAccounts, "PushDevicePage", 200).note("No query or body. Provider tokens are never returned.")
	d.op("Notifications", "DELETE", "/api/v1/me/push-devices/{deviceID}", "Remove own push device registration", allAccounts, "", 204).note("Empty body. Call during logout/account switch while the old account token is available.")
}
